-- W2 schema. Deploy only to an isolated test database until legal and security approval.
CREATE TABLE leads (id CHAR(32) PRIMARY KEY, idem_key CHAR(36) NOT NULL UNIQUE, fingerprint CHAR(64) NOT NULL, payload JSON NOT NULL, status VARCHAR(24) NOT NULL DEFAULT 'NEW', created_at DATETIME NOT NULL) ENGINE=InnoDB;
CREATE TABLE consents (lead_id CHAR(32) PRIMARY KEY, policy_version VARCHAR(100) NOT NULL, consent_version VARCHAR(100) NOT NULL, release_id VARCHAR(100) NOT NULL, marketing_version VARCHAR(100) NULL, marketing_choice VARCHAR(16) NULL, accepted_at DATETIME NOT NULL, FOREIGN KEY (lead_id) REFERENCES leads(id)) ENGINE=InnoDB;
CREATE TABLE telegram_sessions (lead_id CHAR(32) PRIMARY KEY, token_hash CHAR(64) UNIQUE, token_expires_at DATETIME, chat_id BIGINT NULL UNIQUE, step TINYINT NOT NULL DEFAULT 0, answers JSON NULL, FOREIGN KEY (lead_id) REFERENCES leads(id)) ENGINE=InnoDB;
CREATE TABLE telegram_updates (update_id BIGINT PRIMARY KEY, received_at DATETIME NOT NULL) ENGINE=InnoDB;
CREATE TABLE lead_status_history (id BIGINT AUTO_INCREMENT PRIMARY KEY, lead_id CHAR(32) NOT NULL, old_status VARCHAR(24) NOT NULL, new_status VARCHAR(24) NOT NULL, actor_id BIGINT NOT NULL, changed_at DATETIME NOT NULL, FOREIGN KEY (lead_id) REFERENCES leads(id)) ENGINE=InnoDB;
CREATE TABLE outbox (id BIGINT AUTO_INCREMENT PRIMARY KEY, lead_id CHAR(32) NOT NULL, event_type VARCHAR(40) NOT NULL, payload JSON NOT NULL, status VARCHAR(16) NOT NULL DEFAULT 'PENDING', attempts INT NOT NULL DEFAULT 0, available_at DATETIME NOT NULL, created_at DATETIME NOT NULL, FOREIGN KEY (lead_id) REFERENCES leads(id)) ENGINE=InnoDB;
